'use strict';

// MODULES //

var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var bench = require( '@stdlib/bench' );
var UINT32_MAX = require( '@stdlib/constants/uint32/max' );
var words2uint64 = require( '@stdlib/number/uint64/ctor' ).of;
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var pkg = require( './../package.json' ).name;
var isEqual = require( './../lib' );


// VARIABLES //

var options = {
	'dtype': 'uint32'
};

var N = 100;
var values1 = genUint64Values( N );
var values2 = genUint64Values( N );
values1[ 0 ] = values2[ 0 ]; // ensure at least one equal pair


// FUNCTIONS //

/**
* Generates an array of random 64-bit unsigned integers.
*
* @private
* @param {NonNegativeInteger} N - number of elements
* @returns {Array<Uint64>} array of 64-bit unsigned integers
*/
function genUint64Values( N ) {
	var words;
	var out;
	var i;
	var j;

	words = discreteUniform( 2*N, 0, UINT32_MAX, options );
	out = [];
	for ( i = 0; i < N; i++ ) {
		j = 2 * i;
		out.push( words2uint64( words[ j ], words[ j+1 ] ) );
	}
	return out;
}


// MAIN //

bench( pkg, function benchmark( b ) {
	var out;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = isEqual( values1[ i%N ], values2[ i%N ] );
		if ( typeof out !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( out ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
